import{_ as t,c as a,o,ae as n}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Image Element (Pro)","description":"Image Element (Pro)","frontmatter":{"title":"Image Element (Pro)","description":"Image Element (Pro)"},"headers":[],"relativePath":"guide/drag-drop-elements/image-element.md","filePath":"guide/drag-drop-elements/image-element.md"}'),r={name:"guide/drag-drop-elements/image-element.md"};function i(l,e,s,m,d,g){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="image-element-pro" tabindex="-1">Image Element (Pro) <a class="header-anchor" href="#image-element-pro" aria-label="Permalink to &quot;Image Element (Pro)&quot;">​</a></h1><p>Sometimes texts and numbers are not enough to express the information we want to present to users. We absorb information better with visual items like images. Ninja Tables Drag and Drop has an image element for you to add media to the table. Just drag the element to insert image in table. Let’s add the image element in the drag and drop mode to show you how it works. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Image-element-in-tables-1024x509.png" alt="Image element in tables"> When you drag the element on the table, it will show a default image. Change it to whatever you want.</p><h2 id="properties-of-image-element" tabindex="-1"><strong>Properties of Image Element</strong> <a class="header-anchor" href="#properties-of-image-element" aria-label="Permalink to &quot;**Properties of Image Element**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td>Replace Image</td><td>Media Upload</td></tr><tr><td>Alignment</td><td>Left, Center, or Right</td></tr><tr><td>Image Size</td><td>Numeric Value</td></tr><tr><td>Image Shape</td><td>Square or Round</td></tr><tr><td>Image Alternative Text</td><td>Text Edit</td></tr><tr><td>Image Link</td><td>Text Edit for URL</td></tr></tbody></table><ul><li><strong>Replace Image:</strong> Replace the default image with your own image with the Media Upload button from your computer.</li><li><strong>Alignment:</strong> Align the Image to either Left, Center, or Right. By default, it is set to Center.</li><li><strong>Image Size:</strong> Change the size of the Image. By default, it is set to 50.</li><li><strong>Image Shape:</strong> Change the shape of the Image to either square or round. By default, it is set to Square.</li><li><strong>Image Alternative Text:</strong> The alt text of the HTML <code>&lt;a&gt;</code> tag or simply the Alternative text of the link of the image.</li><li><strong>Image Link:</strong> The URL of the link of the image which you can edit within the provided field. Here&#39;s how a table looks with images: <img src="https://ninjatables.com/wp-content/uploads/2023/08/Images-in-data-table-1024x594.png" alt="Images in data table"></li></ul><h2 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h2><p>If you run an online product store, you need a table with product images. This is where Ninja Tables&#39; &quot;Image Element&quot; comes in handy for you. Insert images in WordPress tables easily. Let us know your thoughts and questions.</p>',7)])])}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
